<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@500;600&family=Plus+Jakarta+Sans:wght@600;700&display=swap" rel="stylesheet">
<style>
.apv{--side-w:272px;--hdr-h:64px;--primary:#1E40AF;--primary-d:#00288E;--ink:#131B2E;--muted:#444653;--surface:#FAF8FF;--chip:#F2F3FF;--chip2:#EAEDFF;--line:#E2E7FF;
  font-family:Inter,system-ui,sans-serif;color:var(--ink);background:var(--surface);min-height:100vh;width:100%;position:relative}
.apv *,.apv *::before,.apv *::after{box-sizing:border-box}
.apv h1,.apv h2,.apv h3,.apv p{margin:0}
:where(.apv button){font-family:inherit;cursor:pointer;border:0;background:none;padding:0;color:inherit}
.apv .ic{flex:none;display:block}
.apv .jb{font-family:'JetBrains Mono',monospace}
.apv .pj{font-family:'Plus Jakarta Sans',Inter,sans-serif}
.apv .dot{width:6px;height:6px;border-radius:50%;flex:none;display:inline-block}

/* ---------- Sidebar ---------- */
.apv-side{position:fixed;inset:0 auto 0 0;width:var(--side-w);background:var(--primary);box-shadow:0 1px 8px rgba(0,0,0,.08);
  display:flex;flex-direction:column;justify-content:space-between;z-index:50;overflow-y:auto;transition:transform .25s ease}
.apv-brand{height:var(--hdr-h);padding:0 16px;display:flex;align-items:center;gap:8px;background:rgba(0,40,142,.25);flex:none}
.apv-brand-logo{width:36px;height:36px;border-radius:8px;background:rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center}
.apv-brand b{display:block;color:#fff;font:700 16px/20px 'Plus Jakarta Sans',sans-serif}
.apv-brand small{display:block;color:#B8C4FF;font:500 10px/10px 'JetBrains Mono',monospace;letter-spacing:.5px;text-transform:uppercase}
.apv-sec{padding:8px 12px;color:rgba(184,196,255,.8);font:600 11px/14px Inter,system-ui,sans-serif;letter-spacing:.55px;text-transform:uppercase}
.apv-nav{padding:0 12px;display:flex;flex-direction:column;gap:4px}
.apv-link{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 12px;border-radius:4px;color:#DDE1FF;font:400 14px/20px Inter,system-ui,sans-serif;text-decoration:none;white-space:nowrap}
.apv-link span.l{display:flex;align-items:center;gap:12px;min-width:0}
.apv-link .apv-badge{flex:none}
.apv-link .tx{white-space:normal;line-height:20px}
.apv-link.active{background:rgba(255,255,255,.2)}
.apv-link.strong{color:#fff;font-weight:600}
.apv-link:not(.active):hover{background:rgba(255,255,255,.08);color:#fff}
.apv-link:not(.active):hover .tx{color:#fff}
.apv-link:not(.active):hover .apv-badge.mono{background:rgba(255,255,255,.25);color:#fff}
.apv-badge{padding:2px 6px;border-radius:2px;font:600 12px/16px Inter,system-ui,sans-serif;color:#fff;background:#FD761A}
.apv-badge.mono{background:rgba(255,255,255,.2);color:#DDE1FF;font-family:'JetBrains Mono',monospace}
.apv-divider{height:1px;background:rgba(255,255,255,.15);margin:4px 12px}
.apv-user{margin:0;padding:12px;background:rgba(0,40,142,.2);flex:none}
.apv-user-in{display:flex;align-items:center;gap:8px;padding:8px;border-radius:8px;background:rgba(255,255,255,.05)}
.apv-user-av{width:36px;height:36px;border-radius:8px;background:#3755C3;color:#fff;display:flex;align-items:center;justify-content:center;font:700 13px Inter,system-ui,sans-serif}
.apv-user-in .t{flex:1;min-width:0}
.apv-user-in .t b{display:block;color:#fff;font:600 13px/16px Inter,system-ui,sans-serif;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.apv-user-in .t span{display:flex;align-items:center;gap:4px;color:#B8C4FF;font:400 11px/16px Inter,system-ui,sans-serif}
.apv-scrim{display:none;position:fixed;inset:0;background:rgba(19,27,46,.45);z-index:45}

/* ---------- Content shell ---------- */
.apv-content{margin-left:var(--side-w);min-width:0;min-height:100vh;display:flex;flex-direction:column}
.apv-header{position:sticky;top:0;z-index:30;height:var(--hdr-h);padding:0 24px;display:flex;align-items:center;gap:16px;
  background:rgba(255,255,255,.95);backdrop-filter:blur(12px);box-shadow:0 1px 8px rgba(0,0,0,.04)}
.apv-burger{display:none;width:36px;height:36px;border-radius:4px;background:var(--chip);align-items:center;justify-content:center;flex:none}
.apv-ukm{display:flex;align-items:center;gap:6px;padding:4px 12px;border-radius:4px;background:var(--chip);font:600 13px/16px Inter,system-ui,sans-serif;white-space:nowrap}
.apv-hsep{width:1px;height:24px;background:#DAE2FD;flex:none}
.apv-hsearch{flex:1 1 0;max-width:420px;min-width:0;display:flex;align-items:center;gap:6px;padding:6px 12px;border-radius:4px;background:#fff;box-shadow:0 1px 4px rgba(0,0,0,.04);color:var(--muted);font:400 13px Inter,system-ui,sans-serif}
.apv-hsearch span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.apv-hright{margin-left:auto;display:flex;align-items:center;gap:12px}
.apv-term{display:flex;align-items:center;gap:4px;padding:4px 12px;border-radius:8px;background:var(--chip2);color:var(--muted);font:600 12px/16px Inter,system-ui,sans-serif;white-space:nowrap}
.apv-bell{position:relative;width:36px;height:36px;border-radius:4px;background:var(--chip);display:flex;align-items:center;justify-content:center}
.apv-bell .ic.d{position:absolute;top:6px;right:6px}
.apv-me{display:flex;align-items:center;gap:8px;padding-left:8px}
.apv-me .t{text-align:right;white-space:nowrap}
.apv-me .t b{display:block;font:600 13px/16px Inter,system-ui,sans-serif}
.apv-me .t span{display:block;color:var(--muted);font:500 12px/16px Inter,system-ui,sans-serif}
.apv-me .av{width:32px;height:32px;border-radius:12px;background:var(--primary-d);display:flex;align-items:center;justify-content:center;flex:none}

.apv-main{flex:1;width:100%;max-width:1600px;margin:0 auto;padding:24px 24px 48px;display:flex;flex-direction:column;gap:32px}

/* ---------- Title bar ---------- */
.apv-title{display:flex;flex-wrap:wrap;align-items:flex-end;justify-content:space-between;gap:16px}
.apv-title .l{display:flex;flex-direction:column;gap:4px;min-width:0;flex:1 1 360px;max-width:672px}
.apv-crumb{display:flex;align-items:center;gap:4px;font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;color:var(--muted)}
.apv-crumb b{color:var(--primary-d);font-weight:600}
.apv h1{font:700 clamp(24px,2.4vw,32px)/1.25 'Plus Jakarta Sans',sans-serif;color:var(--ink)}
.apv-title p{font:400 14px/20px Inter,system-ui,sans-serif;color:var(--muted)}
.apv-actions{display:flex;flex-wrap:wrap;gap:12px}
.apv-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:8px 16px;border-radius:4px;font:600 13px/16px Inter,system-ui,sans-serif;white-space:nowrap;text-decoration:none}
.apv-btn.sec{background:var(--chip2);color:var(--ink);box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-btn.pri{background:var(--primary);color:#fff;box-shadow:0 2px 4px -2px rgba(0,0,0,.1),0 4px 6px -1px rgba(0,0,0,.1)}

/* ---------- Metrics ---------- */
.apv-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:20px}
.apv-metric{position:relative;overflow:hidden;background:#fff;border-radius:8px;padding:20px;box-shadow:0 1px 2px rgba(0,0,0,.05);display:flex;flex-direction:column;justify-content:space-between;gap:12px;min-height:140px}
.apv-metric::after{content:"";position:absolute;right:-8px;bottom:-8px;width:64px;height:64px;border-radius:12px;background:var(--tint);opacity:.4;pointer-events:none}
.apv-metric .top{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.apv-metric .top .lb{font:500 13px/16px Inter,system-ui,sans-serif;color:var(--muted)}
.apv-metric .ibox{width:36px;height:36px;border-radius:4px;display:flex;align-items:center;justify-content:center;flex:none}
.apv-metric .num{display:flex;align-items:baseline;gap:4px}
.apv-metric .num b{font:700 28px/34px 'Plus Jakarta Sans',sans-serif}
.apv-metric .num span{font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;color:var(--muted)}
.apv-metric .sub{display:flex;align-items:flex-start;gap:6px;padding-top:4px;font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;position:relative;z-index:1}
.apv-metric .sub .ic,.apv-metric .sub .dot{margin-top:2px}

/* ---------- Toolbar ---------- */
.apv-toolbar{display:flex;flex-direction:column;gap:12px;margin-bottom:-8px}
.apv-tabs{display:flex;gap:4px;overflow-x:auto;padding-bottom:2px;scrollbar-width:none}
.apv-tabs::-webkit-scrollbar{display:none}
.apv-tab{display:inline-flex;align-items:center;gap:6px;padding:7px 12px;border-radius:4px;background:#fff;color:var(--muted);font:500 13px/16px Inter,system-ui,sans-serif;white-space:nowrap;flex:none}
.apv-tab i{font-style:normal;padding:1.5px 4px;border-radius:2px;background:var(--chip2);color:var(--muted);font:500 12px/16px Inter,system-ui,sans-serif}
.apv-tab.on{background:var(--primary);color:#fff;font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-tab.on i{background:rgba(255,255,255,.2);color:#fff;border-radius:12px}
.apv-tab.red i{background:#FFDAD6;color:#BA1A1A;font-weight:600}
.apv-filter{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:8px;background:#fff;border-radius:8px;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-search{flex:1 1 260px;min-width:0;display:flex;align-items:center;gap:6px;padding:6px 12px;border-radius:4px;background:var(--chip);color:var(--muted);font:400 13px Inter,system-ui,sans-serif}
.apv-search span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.apv-dd{display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:4px;background:var(--chip);font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;white-space:nowrap}
.apv-dd.icon{padding:6px 8px}

/* ---------- Cards ---------- */
.apv-list{display:flex;flex-direction:column;gap:20px;container-type:inline-size}
.apv-card{display:grid;grid-template-columns:minmax(220px,288px) 1px minmax(0,1fr) auto;align-items:center;gap:20px;padding:20px;background:#fff;border-radius:8px;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-who{display:flex;gap:12px;align-items:flex-start;min-width:0}
.apv-av{position:relative;flex:none;width:56px;height:56px}
.apv-av img{width:56px;height:56px;border-radius:12px;object-fit:cover;display:block;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-av .bd{position:absolute;right:-6px;bottom:-6px;width:20px;height:20px;border-radius:12px;display:flex;align-items:center;justify-content:center;box-shadow:0 1px 3px rgba(0,0,0,.2)}
.apv-who .n{font:600 16px/24px 'Plus Jakarta Sans',sans-serif;overflow-wrap:anywhere}
.apv-who .nim{font:500 12px/16px 'JetBrains Mono',monospace;color:var(--primary-d)}
.apv-who .prodi{font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;color:var(--muted)}
.apv-status{display:inline-flex;align-items:center;gap:4px;margin-top:6px;padding:2px 6px;border-radius:2px;background:#FFDBCA;color:#783200;font:500 11px/16px Inter,system-ui,sans-serif}
.apv-vsep{align-self:stretch;width:1px;background:var(--line)}
.apv-meta{display:flex;flex-direction:column;gap:6px;min-width:0}
.apv-code{align-self:flex-start;padding:2px 4px;border-radius:2px;background:var(--chip2);color:var(--primary-d);font:600 12px/16px 'JetBrains Mono',monospace}
.apv-meta h3{font:600 16px/24px 'Plus Jakarta Sans',sans-serif;overflow-wrap:anywhere}
.apv-unit{align-self:flex-start;padding:2px 4px;border-radius:2px;background:var(--line);font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px}
.apv-need{display:flex;gap:6px;align-items:flex-start;font:500 13px/18px Inter,system-ui,sans-serif;color:var(--muted)}
.apv-need b{color:var(--ink);font-weight:500}
.apv-need .ic{margin-top:4px}
.apv-chips{display:flex;flex-wrap:wrap;gap:8px;padding-top:2px}
.apv-chip{display:inline-flex;align-items:center;gap:6px;padding:6px 8px;border-radius:2px;background:var(--chip);font:500 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;color:var(--ink);max-width:100%}
.apv-chip>span:not(.hr){min-width:0}
.apv-chip.date{flex-wrap:wrap;row-gap:0}
.apv-chip.date>span:first-of-type{white-space:nowrap}
.apv-chip .hr{font-family:'JetBrains Mono',monospace;color:var(--muted);white-space:nowrap}
.apv-chip.ok{color:#00563A}
.apv-chip.warn{color:#9D4300}
.apv-cta{display:flex;align-items:center;justify-content:flex-end;gap:4px}
.apv-cta .b{padding:6px 12px;border-radius:4px;font:600 13px/16px Inter,system-ui,sans-serif;white-space:nowrap}
.apv-cta .rej{color:#BA1A1A}
.apv-cta .det{background:var(--chip2);color:var(--ink)}
.apv-cta .ok{background:var(--primary);color:#fff;display:inline-flex;align-items:center;gap:6px;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-cta .b:hover{filter:brightness(.96)}

/* ---------- Footer ---------- */
.apv-foot{display:flex;flex-direction:column;gap:20px}
.apv-note{display:flex;align-items:center;gap:12px;padding:12px;background:var(--line);border-radius:8px;box-shadow:0 1px 2px rgba(0,0,0,.05)}
.apv-note .ib{width:40px;height:40px;border-radius:4px;background:var(--primary);display:flex;align-items:center;justify-content:center;flex:none}
.apv-note b{display:block;font:600 16px/24px 'Plus Jakarta Sans',sans-serif;color:var(--primary-d)}
.apv-note p{font:400 13px/18px Inter,system-ui,sans-serif;color:var(--muted)}
.apv-pager{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;padding:4px 0}
.apv-pager .info{font:400 13px/18px Inter,system-ui,sans-serif;color:var(--muted)}
.apv-pager .info b{font-weight:400;color:var(--ink)}
.apv-pager .pg{display:flex;align-items:center;gap:4px}
.apv-pager .pg a,.apv-pager .pg span.pb{min-width:32px;height:32px;padding:0 8px;display:inline-flex;align-items:center;justify-content:center;background:#fff;border-radius:4px;box-shadow:0 1px 2px rgba(0,0,0,.05);font:600 12px/16px Inter,system-ui,sans-serif;letter-spacing:.12px;color:var(--ink);text-decoration:none}
.apv-pager .pg .cur{background:var(--primary)!important;color:#fff!important}

/* ---------- Responsive ---------- */
@container (max-width:1019px){
  .apv-card{grid-template-columns:minmax(200px,260px) 1px minmax(0,1fr)}
  .apv-cta{grid-column:1/-1;justify-content:flex-end;padding-top:12px;border-top:1px solid var(--line)}
}
@container (max-width:599px){
  .apv-card{grid-template-columns:1fr;gap:16px;padding:16px}
  .apv-vsep{width:100%;height:1px;align-self:auto}
  .apv-cta{flex-wrap:wrap;justify-content:stretch}
  .apv-cta .b{flex:1 1 auto;text-align:center;justify-content:center}
}
@media (max-width:1023px){
  .apv-side{transform:translateX(-100%)}
  .apv.open .apv-side{transform:none}
  .apv.open .apv-scrim{display:block}
  .apv-content{margin-left:0}
  .apv-burger{display:flex}
  .apv-ukm,.apv-hsep{display:none}
}
@media (max-width:767px){
  .apv-header{padding:0 12px;gap:8px}
  .apv-main{padding:16px 12px 32px;gap:24px}
  .apv-term,.apv-me .t{display:none}
  .apv-hsearch{max-width:none}
  .apv-actions{width:100%}
  .apv-actions .apv-btn{flex:1 1 auto}
  .apv-note{align-items:flex-start}
}
@media (max-width:479px){
  .apv-hsearch{display:none}
  .apv-hright{margin-left:auto}
}
</style>

